from decimal import Decimal
from typing import Any


def _value(record: dict | None, key: str) -> Any:
    if not record:
        return ""
    value = record.get(key, "")
    return "" if value is None else value


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _numeric_eq(value: Any, expected: int | str) -> bool:
    return _number(value) == Decimal(str(expected))


def _date_ge(value: Any, today: str) -> bool:
    value = _value({"VALUE": value}, "VALUE")
    if value in ("", "00000000") or today == "00000000":
        return False
    return str(value) >= today


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    stat_cd = _value(record, "STAT_CD")
    amount = _value(record, "AMT")
    lost_reason = _value(record, "LOST_RSN")
    close_dt = _value(record, "CLOSE_DT")
    stage_pct = _value(record, "STAGE_PCT")
    old_stat_cd = _value(old, "STAT_CD") if event == "UPDATE" else ""

    if event in ("INSERT", "UPDATE"):
        if not (_number(amount) >= Decimal("0")):
            errors.append({
                "code": "E3001",
                "message": "Amount negative",
                "severity": "BLOCK",
            })

        if not (not (stat_cd == "W" and _number(amount) == Decimal("0"))):
            errors.append({
                "code": "E3002",
                "message": "Won opportunity requires amount",
                "severity": "BLOCK",
            })

        if not (not (stat_cd == "L" and lost_reason == "")):
            errors.append({
                "code": "E3003",
                "message": "Lost reason required",
                "severity": "BLOCK",
            })

        if not (not (stat_cd == "W" and close_dt == "00000000")):
            errors.append({
                "code": "E3004",
                "message": "Won opportunity requires close date",
                "severity": "BLOCK",
            })

    if event == "UPDATE":
        if not (not (old_stat_cd == "W" and stat_cd != "W")):
            errors.append({
                "code": "E3005",
                "message": "Cannot reopen a won opportunity",
                "severity": "BLOCK",
            })

    if event in ("INSERT", "UPDATE"):
        stage_consistent = (
            (stat_cd == "P" and _numeric_eq(stage_pct, 10))
            or (stat_cd == "Q" and _numeric_eq(stage_pct, 25))
            or (stat_cd == "N" and _numeric_eq(stage_pct, 60))
            or (stat_cd == "W" and _numeric_eq(stage_pct, 100))
            or (stat_cd == "L" and _numeric_eq(stage_pct, 0))
        )
        if not stage_consistent:
            errors.append({
                "code": "E3006",
                "message": "Stage percent inconsistent with status",
                "severity": "BLOCK",
            })

    if event == "INSERT":
        if not (close_dt == "00000000" or _date_ge(close_dt, today)):
            errors.append({
                "code": "E3007",
                "message": "Close date in past",
                "severity": "WARN",
            })

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
